quests[8819] = { id = 8819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with Darnassus.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
