quests[8938] = { id = 8938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", sourceObjective = "Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Mokvar in Orgrimmar.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", sourceObjectiveStatus = "unverified-source-field" }
