quests[8957] = { id = 8957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Mokvar in Orgimmar with a set of Boots of Elements, Kilt of Elements and Pauldrons of Elements.", progress = "You've returned and I see in your eyes that you've much to tell me, {name}.  Let us take care of your reward first.", completion = "This curse was bestowed upon us but for a mere medallion.  Lord Valthalak certainly knows how to hold a grudge.\n\nWe'll endeavor to find the remaining pieces - hopefully before I meet an untimely demise.  But before that, let us see about your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[8958] = { id = 8958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Dreadmist Sandals, Dreadmist Leggings and Dreadmist Mantle.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[8959] = { id = 8959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Boots of Valor, Legplates of Valor and Spaulders of Valor.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[8960] = { id = 8960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodley's Unfortunate Fate", description = "So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.\n\nI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened.", sourceObjective = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.", completion = "I am so glad that you can see me. Finally someone to talk to!\n\nWill you help us, {name}? Help to undo the wrong that we perpetrated and put things to right? If it's true that you already have the Top Piece of Lord Valthalak's Amulet, then I think I can point you in the right direction to acquire the other two parts, reunite them and put an end to all of this.\n\nOh, by the way, hello, my name is Bodley. Nice to meet you!", sourceObjectiveStatus = "unverified-source-field" }
quests[8961] = { id = 8961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Kings of Flame", description = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.\n\nThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them.", sourceObjective = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.", progress = "It was our folly... our doom that we took that last job. If only we hadn't inadvertently stolen Lord Valthalak's spirit, which was contained in the amulet; if only there weren't those in our mercenary group that had been so greedy and divided it up amongst themselves. I'd be alive today, maybe tossing back a beer, or tossing one of my kids into the air.\n\n{name}, don't let the avarice of the ignoble in our old mercenary company be your doom as well.", completion = "I'm impressed, {class}, but there's no time to lose. I will give you your next task, because you will still need to acquire a few more important components before we can proceed.\n\nSpeak to me again when you feel that you are ready for the challenge that lies ahead.", sourceObjectiveStatus = "unverified-source-field" }
quests[8962] = { id = 8962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components of Importance", description = "{class}, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", sourceObjective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the remains into the brazier.\n\nNow all that is left is to go to the lower portion of Blackrock Spire, to the chamber where War Master Voone resides in Tazz'Alaor, and use the brazier to summon forth the corrupted spirit of my former cohort, Mor Grayhoof. He cannot rest until the amulet piece is taken from him.", sourceObjectiveStatus = "unverified-source-field" }
quests[8963] = { id = 8963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components of Importance", description = "{class}, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.", sourceObjective = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the relic into the brazier.\n\nNow all that is left is to go to the Shrine of Eldretharr in the east wing of Dire Maul, and use the brazier to summon forth the spirit of my former cohort, Isalien. Her spirit has been corrupted by her possession of the piece of Valthalak's amulet, and the portion of his soul within it.", sourceObjectiveStatus = "unverified-source-field" }
quests[8964] = { id = 8964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components of Importance", description = "{class}, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.", sourceObjective = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the sword into the brazier.\n\nNow all that is left is to get into The Crimson Throne inside The Scarlet Bastion at Stratholme, and use the brazier to summon forth the remains of my former cohorts, Jarien and Sothos. Their souls have been twisted further by their possession of Valthalak's amulet piece and his spirit within.", sourceObjectiveStatus = "unverified-source-field" }
quests[8965] = { id = 8965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components of Importance", description = "{class}, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", sourceObjective = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the ashes into the brazier.\n\nNow all that is left is to get into Scholomance, to Ras Frostwhisper's chamber, and use the brazier to summon forth the spirit of my former cohort, Kormok. The amulet piece, and Valthalak's spirit within, has corrupted him even further, and he will not rest until you forcibly take it from him.", sourceObjectiveStatus = "unverified-source-field" }
quests[8966] = { id = 8966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Left Piece of Lord Valthalak's Amulet", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Then it is done? You have retrieved the Left Piece of Lord Valthalak's Amulet and finally put to rest the spirit of my old companion, Mor Grayhoof?", completion = "You have done a great thing, {name}. One spirit rests in peace, but there is still much work to be done before we can put all of this behind us.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[8967] = { id = 8967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Left Piece of Lord Valthalak's Amulet", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Surely you haven't already dealt with the salvation of Isalien's spirit and the retrieval of the Left Piece of Lord Valthalak's Amulet, {name}?", completion = "Thank you, {name}, for putting Isalien's spirit to rest. Now, perhaps, she will find peace with her goddess. But, there is still a great deal of work ahead of us if we are to get out of this fine pickle we find ourselves in.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[8968] = { id = 8968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Left Piece of Lord Valthalak's Amulet", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the Left Piece of Lord Valthalak's Amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", sourceObjective = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Does this mean then, {class}, that you've already put the souls of those two fools to rest and retrieved the Left Piece of Lord Valthalak's Amulet?", completion = "I suppose it's for the best that the souls of those two have finally been put to rest, even if I didn't like them while they were alive. In any case, we have what we were after, and that is definitely a good thing!\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[8969] = { id = 8969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Left Piece of Lord Valthalak's Amulet", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "I commend you, {name}, if you have returned with the left piece of the amulet. If not, however, please take care of that as there is no time to waste, I assure you!", completion = "Good work, {name}! Kormok wasn't all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. But, there is more work ahead of us.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[8970] = { id = 8970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I See Alcaz Island In Your Future...", description = "As I was saying, {class}, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.\n\nThis is where you come in, {name}. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there.", sourceObjective = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain.", progress = "Bloodkelp, {name}, a big stack of it, that's what I need to power my divinatory spells. You're likely to need to take at least a couple of friends along with you to Alcaz Island to gather it up... those Strashaz are a nasty lot!", completion = "To be honest, {name}, I'm surprised you made it back in one piece. Then again, I guess Alcaz Island is the least of your worries right now.\n\nOk, give me a moment here... divination isn't something that you can just snap your fingers and expect accurate answers from.", sourceObjectiveStatus = "unverified-source-field" }
quests[8971] = { id = 8971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8972] = { id = 8972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8973] = { id = 8973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8974] = { id = 8974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8975] = { id = 8975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8976] = { id = 8976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8977] = { id = 8977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Deliana", description = "It's been great working with you, {name}.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", sourceObjective = "Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge.", progress = "You've returned?", completion = "Excellent!  You've done well, {name}.  I'm not sure I trust the goblin's craftsmanship, but I'm left with no other choice.", sourceObjectiveStatus = "unverified-source-field" }
quests[8978] = { id = 8978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mokvar", description = "It's been great working with you, {name}.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", sourceObjective = "Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer.", progress = "You've returned with the device?", completion = "You've returned with the device!  I'm impressed by your dedication, {name}.  Excellent work.", sourceObjectiveStatus = "unverified-source-field" }
quests[8979] = { id = 8979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenstad's Hunch", description = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.", sourceObjective = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.", progress = "How may I serve you?", completion = "Another one of Fenstad's obsessions, I see. Does he think that the Royal Apothecary Society has nothing better to do than to perform his little investigations?\n\nVery well, I will humor him once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[8980] = { id = 8980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinge's Assessment", description = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.", sourceObjective = "Return to Fenstad Argyle outside the bank in the Undercity.", completion = "So, I was right. We must waste no time. We must determine the source of these tainted fragrances.\n\nHere, to repay you for the purchase of the cologne and perfume.", sourceObjectiveStatus = "unverified-source-field" }
quests[8981] = { id = 8981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift Giving", progress = "Have you come to deliver a present of love and adoration to your favorite leader?", completion = "Wonderful! Wonderful! I will add this to the pile of other gifts.\n\nI didn't expect so many! You must truly love your leaders.\n\nNow, let me just add one more to the count..." }
quests[8982] = { id = 8982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracing the Source", description = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.", sourceObjective = "Speak with Innkeeper Norman in the Undercity.", completion = "Ah yes, I just recently received stock of the perfume and cologne. I don't know how long I can keep it on the shelves - seems like no one can get enough of it.\n\nIf you ask me, I don't see what the big deal is.", sourceObjectiveStatus = "unverified-source-field" }
quests[8983] = { id = 8983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracing the Source", description = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Mage Quarter.", sourceObjective = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.", completion = "I'm afraid I sold my entire supply of perfume and cologne to Norman, the innkeeper. If you'd like some, you should speak with him - assuming he has any left.\n\nYou shouldn't waste any time, though. I think you'll find the cologne  irresistible.", sourceObjectiveStatus = "unverified-source-field" }
quests[8984] = { id = 8984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source Revealed", description = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.", sourceObjective = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.", completion = "Yes, I made those fragrances. Wonderful smell, isn't it? Irresistible.\n\nOnce the warriors of Alliance and Horde alike are smitten with these feelings of love, they will be powerless to stop the rise of the Shadow Council.\n\nThey will be weakened, unprepared. As they worry for their loved ones, they will lose their edge.\n\nThe solution was so simple. Why did it take me so long to come upon it? The weakness of all is through the heart. And there is nothing you can do to stop the inevitable.", sourceObjectiveStatus = "unverified-source-field" }
quests[8985] = { id = 8985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.", sourceObjective = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the relic into the brazier.\n\nNow all that is left is to go to the Shrine of Eldretharr in the east wing of Dire Maul, and use the brazier to summon forth the spirit of my former cohort, Isalien. Her spirit has been corrupted by her possession of the piece of Valthalak's amulet, and the portion of his soul within it.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[8986] = { id = 8986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", sourceObjective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the remains into the brazier.\n\nNow all that is left is to go to the lower portion of Blackrock Spire, to the chamber where War Master Voone resides in Tazz'Alaor, and use the brazier to summon forth the corrupted spirit of my former cohort, Mor Grayhoof. He cannot rest until the amulet piece is taken from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[8987] = { id = 8987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.", sourceObjective = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the sword into the brazier.\n\nNow all that is left is to get into The Crimson Throne inside The Scarlet Bastion at Stratholme, and use the brazier to summon forth the remains of my former cohorts, Jarien and Sothos. Their souls have been twisted further by their possession of Valthalak's amulet piece and his spirit within.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[8988] = { id = 8988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", sourceObjective = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the ashes into the brazier.\n\nNow all that is left is to get into Scholomance, to Ras Frostwhisper's chamber, and use the brazier to summon forth the spirit of my former cohort, Kormok. The amulet piece, and Valthalak's spirit within, has corrupted him even further, and he will not rest until you forcibly take it from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[8989] = { id = 8989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Then it is done? You have retrieved the Right Piece of Lord Valthalak's Amulet, recombined the amulet into one whole, and finally put to rest the spirit of my old companion, Mor Grayhoof?", completion = "Thank you for helping Mor Grayhoof, {name}. Another spirit rests in peace, and we now have the reassembled amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8990] = { id = 8990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Surely you haven't already dealt with the salvation of Isalien's spirit and the retrieval of the Right Piece of Lord Valthalak's Amulet, {name}? Be sure to recombine the pieces of the amulet before handing it to me.", completion = "Thank you, {name}, for putting Isalien's spirit to rest. Now, perhaps, she will find peace with her goddess. And, we have the reassembled amulet, as well! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8991] = { id = 8991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the Right Piece of Lord Valthalak's Amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", sourceObjective = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "Does this mean then, {class}, that you've already put the souls of those two fools to rest and recombined the pieces of Lord Valthalak's Amulet?", completion = "I suppose it's for the best that the souls of those two have finally been put to rest, even if I didn't like them while they were alive. In any case, we have what we were after, and now the amulet is reassembled! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8992] = { id = 8992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning next.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", sourceObjective = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", progress = "I commend you, {name}, if you have returned with the completed amulet. If not, however, please take care of that as there is no time to waste, I assure you!", completion = "Good work, {name}! Kormok wasn't all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. And now we have the completed amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8993] = { id = 8993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift Giving", progress = "Have you come to deliver a present of love and adoration to your favorite leader?", completion = "Wonderful! Wonderful! I will add this to the pile of other gifts.\n\nI didn't expect so many! You must truly love your leaders.\n\nNow, let me just add one more to the count..." }
quests[8994] = { id = 8994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Preparations", description = "We're nearly there, {class}. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.\n\nTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.\n\nGood luck, {name}!", sourceObjective = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.", progress = "We've come a long way, {name}, and I just wanted to say that no matter what happens, thank you! You've put yourself in mortal danger to try to help the surviving members of our mercenary company, The Veiled Blade, and as far as I'm concerned, you're one of us now.", completion = "That's it then. I'll extract the metal from the bracers and imbue the brazier with these final components. Then it will be ready for you to summon Lord Valthalak, and finally return his spirit amulet to him.\n\nYou've come quite a distance, {name}, don't falter now that the end is in sight!", sourceObjectiveStatus = "unverified-source-field" }
quests[8995] = { id = 8995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mea Culpa, Lord Valthalak", description = "All is now ready, {name}.\n\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\n\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\n\nGood luck!", sourceObjective = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", progress = "{class}, you dare disturb my rest!", completion = "How fortunate for you that I know you're not part of the original group that stole this from me.\n\nI'll take back what is mine now, mortal! Give the amulet to me!", sourceObjectiveStatus = "unverified-source-field" }
